t.script:
(function(){
  var f = document.getElementById('dmn_q_form');
  var box = document.getElementById('dmn_q_alert');
  var btn = document.getElementById('dmn_q_submit');
  var result = document.getElementById('dmn_q_result');
  var tipo = document.getElementById('dmn_q_tipo');
  var medWrap = document.getElementById('dmn_q_medida_wrap');
  var medSel = document.getElementById('dmn_q_medida');
  var medTextWrap = document.getElementById('dmn_q_medida_text_wrap');
  var medText = document.getElementById('dmn_q_medida_text');

  // Anillo -> Medida es talla (dropdown del atributo); otro tipo -> texto libre.
  function toggleMedida(){
    var o = tipo.options[tipo.selectedIndex];
    var ring = !!(o && o.getAttribute('data-ring') === '1');
    medWrap.style.display = ring ? 'block' : 'none';
    medTextWrap.style.display = ring ? 'none' : 'block';
    if(ring){ medText.value = ''; } else { medSel.value = ''; }
  }
  tipo.addEventListener('change', toggleMedida);
  toggleMedida();

  // Gema montada: al salir del campo se confirma cuál es, para que
  // un número mal tecleado se vea ANTES de crear la pieza.
  var gemaInput = document.getElementById('dmn_q_gema');
  var gemaInfo = document.getElementById('dmn_q_gema_info');
  var gemaHelp = gemaInfo.textContent;
  gemaInput.addEventListener('blur', function(){
    var code = gemaInput.value.trim();
    if(!code){ gemaInfo.className = 'form-text'; gemaInfo.textContent = gemaHelp; return; }
    gemaInfo.className = 'form-text'; gemaInfo.textContent = 'Buscando…';
    fetch('/dmn/alta/gema', {method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({jsonrpc:'2.0', method:'call', params:{codigo: code}, id:1})})
    .then(function(r){return r.json();})
    .then(function(d){
      var res = d.result || {};
      if(res.ok){
        gemaInfo.className = 'form-text text-success';
        gemaInfo.textContent = '✔ ' + res.name + (res.detalle ? ' — ' + res.detalle : '');
      } else {
        gemaInfo.className = 'form-text text-danger';
        gemaInfo.textContent = res.error || 'No se encontró esa gema.';
      }
    })
    .catch(function(){
      gemaInfo.className = 'form-text text-danger';
      gemaInfo.textContent = 'No se pudo verificar la gema.';
    });
  });

  function readFiles(input){
    var files = input.files ? Array.prototype.slice.call(input.files) : [];
    return Promise.all(files.map(function(file){
      return new Promise(function(resolve){
        var r = new FileReader();
        r.onload = function(){ resolve(r.result); };
        r.onerror = function(){ resolve(null); };
        r.readAsDataURL(file);
      });
    })).then(function(arr){ return arr.filter(Boolean); });
  }

  f.addEventListener('submit', function(e){
    e.preventDefault();
    box.innerHTML = '';
    btn.disabled = true; btn.textContent = 'Creando...';
    readFiles(f.imagenes).then(function(imgs){
      var p = {
        joya: f.joya.value, categ_id: f.categ_id.value,
        metal_value_id: f.metal_value_id.value,
        medida_value_id: medSel.value, medida_text: medText.value,
        ancho: f.ancho.value, grosor: f.grosor.value,
        descripcion: document.getElementById('dmn_q_desc').value,
        peso: f.peso.value, codigo: f.codigo.value,
        gema_codigo: gemaInput.value, imagenes: imgs
      };
      return fetch('/dmn/alta/crear', {method:'POST', headers:{'Content-Type':'application/json'},
        body: JSON.stringify({jsonrpc:'2.0', method:'call', params:p, id:1})});
    })
    .then(function(r){return r.json();})
    .then(function(d){
      btn.disabled = false; btn.textContent = 'Crear pieza';
      var res = d.result || {};
      if(res.ok){
        f.style.display = 'none';
        var qr = document.getElementById('dmn_q_qr');
        qr.src = '/report/barcode?barcode_type=QR&value=' + encodeURIComponent(res.visor_url) + '&width=260&height=260';
        var link = document.getElementById('dmn_q_link');
        link.href = res.visor_url;
        result.style.display = 'block';
        result.scrollIntoView({behavior:'smooth'});
      } else {
        box.innerHTML = '<div class="alert alert-danger">' + (res.error || 'No se pudo crear la pieza.') + '</div>';
      }
    })
    .catch(function(){
      btn.disabled = false; btn.textContent = 'Crear pieza';
      box.innerHTML = '<div class="alert alert-danger">Error de conexión.</div>';
    });
  });

  // Botón "Describir con IA": manda la(s) foto(s) + contexto y rellena el textarea.
  document.getElementById('dmn_q_ai').addEventListener('click', function(){
    var st = document.getElementById('dmn_q_ai_status');
    var aiBtn = document.getElementById('dmn_q_ai');
    var metalSel = document.getElementById('dmn_q_metal');
    readFiles(f.imagenes).then(function(imgs){
      if(!imgs.length){ st.textContent = 'Sube una foto primero.'; return; }
      aiBtn.disabled = true; st.textContent = 'Generando…';
      var tOpt = tipo.options[tipo.selectedIndex];
      var mOpt = metalSel.options[metalSel.selectedIndex];
      var medidaTxt = (medWrap.style.display !== 'none')
        ? ((medSel.options[medSel.selectedIndex]||{}).text || '')
        : medText.value;
      var p = {
        imagenes: imgs, joya: f.joya.value,
        tipo: (tOpt ? tOpt.text : ''),
        metal: (mOpt ? mOpt.text : ''),
        peso: f.peso.value, medida: medidaTxt
      };
      return fetch('/dmn/alta/describir', {method:'POST', headers:{'Content-Type':'application/json'},
        body: JSON.stringify({jsonrpc:'2.0', method:'call', params:p, id:1})})
      .then(function(r){return r.json();})
      .then(function(d){
        aiBtn.disabled = false;
        var res = d.result || {};
        if(res.ok){ document.getElementById('dmn_q_desc').value = res.descripcion || ''; st.textContent = 'Listo, revisa y edita.'; }
        else { st.textContent = res.error || 'No se pudo generar.'; }
      });
    }).catch(function(){ aiBtn.disabled = false; st.textContent = 'Error de conexión.'; });
  });

  document.getElementById('dmn_q_again').addEventListener('click', function(){
    f.reset(); toggleMedida(); document.getElementById('dmn_q_ai_status').textContent = '';
    gemaInfo.className = 'form-text'; gemaInfo.textContent = gemaHelp;
    f.style.display = 'block'; result.style.display = 'none'; box.innerHTML = '';
    window.scrollTo({top:0, behavior:'smooth'});
  });
})();

(function(){
  var f = document.getElementById('dmn_reg_form');
  var box = document.getElementById('dmn_reg_alert');
  f.addEventListener('submit', function(e){
    e.preventDefault();
    var p = {token: f.token.value, name: f.name.value, email: f.email.value, phone: f.phone.value};
    fetch('/dmn/claim', {method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({jsonrpc:'2.0', method:'call', params:p, id:1})})
    .then(function(r){return r.json();})
    .then(function(d){
      var res = d.result || {};
      if(res.ok){
        var g = res.warranty_until ? (' Garantia hasta ' + res.warranty_until + '.') : '';
        box.innerHTML = '<div class="alert alert-success">Listo, ' + res.partner + '. Tu joya quedo registrada a tu nombre.' + g + '</div>';
        f.style.display = 'none';
        setTimeout(function(){ window.location.href='/visor'; }, 2500);
      } else {
        box.innerHTML = '<div class="alert alert-danger">' + (res.error || 'No se pudo registrar.') + '</div>';
      }
    })
    .catch(function(){ box.innerHTML = '<div class="alert alert-danger">Error de conexion.</div>'; });
  });
})();

xpath.script:
(function(){
  fetch('/dmn/dedication', {method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({jsonrpc:'2.0', method:'call', params:{}, id:1})})
  .then(function(r){return r.json();})
  .then(function(d){
    var res = d.result || {};
    if(!res.visible){return;}
    document.getElementById('dmn_ded_text').textContent = res.text || '';
    document.getElementById('dmn_ded_from').textContent = res.from ? ('- ' + res.from) : '';
    if(res.image){ var im = document.getElementById('dmn_ded_img'); im.src = res.image; im.style.display='block'; }
    document.getElementById('dmn_dedication_block').style.display = 'flex';
  }).catch(function(){});
})();
